// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;

    function setUp() public {
        c = new RoundFactory();
        c.initialize();
    }

    function testFuzz_property(address newOwner, address caller) public {
        vm.assume(newOwner != address(0));
        vm.assume(caller != newOwner);

        vm.prank(c.owner());
        c.transferOwnership(newOwner);

        // owner() must return the stored owner, independent of who calls it.
        assertTrue(c.owner() == newOwner);
    }
}
